glass_system.glass_class:
.glass {
  background: var(--surface-1);
  backdrop-filter: blur(28px) saturate(140%);
  -webkit-backdrop-filter: blur(28px) saturate(140%);
  border-radius: 1.5rem;
  box-shadow: 0 24px 60px -20px rgba(80, 40, 160, 0.45);
  position: relative;
}
.glass::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 1.5rem;
  padding: 0.5px;
  background: linear-gradient(135deg, rgba(255,255,255,0.28), rgba(157,123,245,0.14) 50%, transparent);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
